 string VerifyFinal3D(){int assets=Final3DAssets.Audit();var account=save;bool previous=verifying;int oldHero=heroIndex,oldDragon=selectedDragon,oldCurse=selectedCurse;verifying=true;save=new SaveData{dragonUnlocks=7};selectedDragon=1;selectedCurse=-1;heroIndex=0;StartRun();time=Duration;SpawnWaves(.01f);if(!final3DActive||!final3DTransition||finalBoss==null)throw new Exception("Final 3D transition missing");float gameTime=time;Tick(.05f);if(time!=gameTime)throw new Exception("Combat advanced during transition");for(int i=0;i<80;i++)AdvanceFinalTransition(.05f);FinalCamera();SyncFinal3D();if(cam.orthographic||!final3DVisible||pixelFinal.Count<3)throw new Exception("3D camera/models not activated");foreach(var r in world.GetComponentsInChildren<SpriteRenderer>())if(!r.transform.IsChildOf(finalWorld)&&!r.forceRenderingOff)throw new Exception("Original XY sprite remained visible in 2.5D final");VerifyPixelPresentation();var p=FinalPoint(pos+new Vector2(2,1));var screen=cam.WorldToScreenPoint(p);if(Vector2.Distance(ArenaPointFromScreen(screen),pos+new Vector2(2,1))>.03f)throw new Exception("3D cursor plane mapping failed");Damage(finalBoss,finalBoss.maxHp+1);if(state!=ScreenState.Result||save.wins!=1)throw new Exception("3D final victory failed");ReturnMenu();if(final3DActive||!cam.orthographic||cam.transform.rotation!=Quaternion.identity)throw new Exception("3D camera failed to reset");int coins=save.coins,wins=save.wins,owned=save.relicOwned,kills=save.dragonKills;StartFinal3DDemo();for(int i=0;i<80;i++)AdvanceFinalTransition(.05f);var extra=SpawnEnemy(3,false);Damage(extra,extra.maxHp+1);CollectRelic(2);Damage(finalBoss,finalBoss.maxHp+1);if(save.coins!=coins||save.wins!=wins||save.relicOwned!=owned||save.dragonKills!=kills)throw new Exception("3D demo changed saved progress");StartRun();if(final3DActive||final3DDemo||!cam.orthographic)throw new Exception("3D mode leaked into new run");save=account;heroIndex=oldHero;selectedDragon=oldDragon;selectedCurse=oldCurse;ver